using System;
using UnityEngine;
namespace COW.GamePlay {
 public partial class SceneEditBoxSelectTool {
  public static Texture2D MzBadgeTexture;
  public static bool MzBadgeAssetInvalid;
  public static int MzBadgeAttempts;
  public static float MzBadgeRetry;
  public static string[] MzGlassHashes;
  // Checks once at decode time, never hashes an image each render frame.
  // A modified verifier can bypass this; signed proxy packages cover original releases.
  public static Texture2D MzCheckedImage(string data,string expected) {
   if(data==null||expected==null||MzHash(data)!=expected)throw new InvalidOperationException("Menu asset integrity mismatch");
   return MzPng(data,FilterMode.Bilinear);
  }
  public static string MzBadgeImage(){return "";}
  public static string MzBadgeImageHash(){return "5634921b2aaae28d7634aa2c486d4949b3783046bc7a46e1092c8cd0be9ef758";}
  public static string[] MzGlassImageHashes(){return new string[]{"c39494cb9e21bee4ac18fcd0d4ef28cd2034b7aee3ae7750304fbfe37e83b27c","e3d8aa012501b9f18408fa8c136535405682507408afa5b1534d36767ee56a8a","08c85d611fa2a6b779cba2094a29a34da2d526cf0b665554ac34a2895d247e35","16c6b63c35b278e6327e96c55f9b29abeb68578d203cdee73a86141aabc239f1","2c01955909eee595f61d53b8ec8553dfb0295a44d2844b9a3d9123d5d7b487a0","c20c65431604b9c243a48fe24989c0d1fe184bd3d9598082d648d9d591660913","fad3f95c03471bdd0e02d05a5dbf6ca067925837d192733310555df51d4f55db","59ee19e078a0a7a3492013675fb19d7d223f38e64b0d5429338c70b213a4e50d","6822e725f285205bb26f3af9900527479fe24c52d288da14e7a7731741610f46","93bd4bbb9a44dc6bf56ac1a7809a38f69d877591d98963b54851b5c6860b12aa","778267dda6ac613683e362666f2b280bfdd730e248df1298811e30501e00a2b7","5bf7c8e0a1bfd03c27162c99b2f831197060822942278b48ca66731000999710","b143fb1408e7d972477c15992a19e59bb730017ad24e8d4cddd5c9e743e37eb6","fae18f72f949fdf38e234a456aeb893754d7aa2528d9762d7aeef1f603f464b0","e67c8a1ac9c579750c191a8f886f4dd135ee423373f9825c9af4625b56986c53"};}
  public static void MzBadgeImageInit(){
   if(MzBadgeTexture!=null||MzBadgeAssetInvalid||MzBadgeAttempts>=3||Time.realtimeSinceStartup<MzBadgeRetry)return;
   MzBadgeAttempts++;MzBadgeRetry=Time.realtimeSinceStartup+5;
   try{
    string data=MzBadgeImage();
    if(MzHash(data)!=MzBadgeImageHash()){MzBadgeAssetInvalid=true;return;}
    MzBadgeTexture=MzPng(data,FilterMode.Bilinear);
   }catch(Exception){}
  }
 }
}
